from pathlib import Path
import posixpath, re, zipfile
import xml.etree.ElementTree as ET
from xml.sax.saxutils import escape

pptx = Path('/home/user/Desktop/Dickinson_Slides.pptx')
out = Path('/home/user/Desktop/notes.docx')

NS = {
    'p': 'http://schemas.openxmlformats.org/presentationml/2006/main',
    'a': 'http://schemas.openxmlformats.org/drawingml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'rel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}
R_ID = '{%s}id' % NS['r']

def rels_map(xml_bytes):
    root = ET.fromstring(xml_bytes)
    return {rel.get('Id'): (rel.get('Target'), rel.get('Type', '')) for rel in root.findall('rel:Relationship', NS)}

def resolve(base_path, target):
    if target.startswith('/'):
        return target.lstrip('/')
    return posixpath.normpath(posixpath.join(posixpath.dirname(base_path), target))

def paragraph_text(a_p):
    parts = []
    for elem in a_p.iter():
        if elem.tag == '{%s}t' % NS['a']:
            parts.append(elem.text or '')
        elif elem.tag == '{%s}br' % NS['a']:
            parts.append('\\n')
    return ''.join(parts)

def notes_paragraphs(z, notes_path):
    root = ET.fromstring(z.read(notes_path))
    result = []
    for sp in root.findall('.//p:sp', NS):
        ph = sp.find('.//p:ph', NS)
        if ph is None or ph.get('type') "'!= '"'body':
            continue
        tx = sp.find('p:txBody', NS)
        if tx is None:
            continue
        for a_p in tx.findall('a:p', NS):
            text = paragraph_text(a_p).strip()
            if text:
                result.append(text)
    return result

all_notes = []
with zipfile.ZipFile(pptx) as z:
    pres = ET.fromstring(z.read('ppt/presentation.xml'))
    pres_rels = rels_map(z.read('ppt/_rels/presentation.xml.rels'))
    for sld_id in pres.findall('.//p:sldId', NS):
        target, _ = pres_rels[sld_id.get(R_ID)]
        slide_path = resolve('ppt/presentation.xml', target)
        rel_path = posixpath.dirname(slide_path) + '/_rels/' + posixpath.basename(slide_path) + '.rels'
        if rel_path not in z.namelist():
            continue
        for rel_id, (rel_target, rel_type) in rels_map(z.read(rel_path)).items():
            if rel_type.endswith('/notesSlide'):
                notes_path = resolve(slide_path, rel_target)
                if notes_path in z.namelist():
                    all_notes.extend(notes_paragraphs(z, notes_path))
                break

# Build a small, valid DOCX with plain paragraphs only.
def w_text_run(text):
    segments = text.split('\\n')
    run_parts = []
    for i, segment in enumerate(segments):
        if i:
            run_parts.append('<w:br/>')
        run_parts.append(f'<w:t xml:space=\"preserve\">{escape(segment)}</w:t>')
    return '<w:r>' + ''.join(run_parts) + '</w:r>'

body = ''.join(f'<w:p>{w_text_run(note)}</w:p>' for note in all_notes)
document_xml = f'''<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>
<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\">
  <w:body>{body}<w:sectPr><w:pgSz w:w=\"12240\" w:h=\"15840\"/><w:pgMar w:top=\"1440\" w:right=\"1440\" w:bottom=\"1440\" w:left=\"1440\" w:header=\"720\" w:footer=\"720\" w:gutter=\"0\"/></w:sectPr></w:body>
</w:document>'''
content_types = '''<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>
<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">
  <Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/>
  <Default Extension=\"xml\" ContentType=\"application/xml\"/>
  <Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/>
</Types>'''
root_rels = '''<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>
<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">
  <Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"word/document.xml\"/>
</Relationships>'''
with zipfile.ZipFile(out, 'w', compression=zipfile.ZIP_DEFLATED) as z:
    z.writestr('[Content_Types].xml', content_types)
    z.writestr('_rels/.rels', root_rels)
    z.writestr('word/document.xml', document_xml)
print(f'Wrote {out} with {len(all_notes)} note paragraphs')
for note in all_notes:
    print(note)
